import { lstat, rm } from 'node:fs/promises';
import path from 'node:path';

const ownedFolders = new Map();
export async function registerInstalledSkill(destination) {
  const info = await lstat(destination, { bigint: true });
  if (!info.isDirectory() || info.isSymbolicLink()) throw new Error('安装目录已发生变化，请重新安装。');
  ownedFolders.set(path.resolve(destination), { dev: info.dev, ino: info.ino, birthtimeNs: info.birthtimeNs, created: Date.now() });
  if (ownedFolders.size > 1000) for (const [key, item] of ownedFolders) if (item.created < Date.now() - 30 * 60 * 1000) ownedFolders.delete(key);
}

// Discovery failure or a failed batch may clean up only the exact folder that
// this process created. A folder replaced by the user is never removed.
export async function removeInstalledSkill(destination) {
  const key = path.resolve(destination), expected = ownedFolders.get(key);
  if (!expected) throw new Error('安装目录的归属无法确认，已保留现有文件。');
  const info = await lstat(key, { bigint: true }).catch(error => { if (error.code === 'ENOENT') return null; throw error; });
  if (!info) { ownedFolders.delete(key); return; }
  if (!info.isDirectory() || info.isSymbolicLink() || info.dev !== expected.dev || info.ino !== expected.ino || info.birthtimeNs !== expected.birthtimeNs) throw new Error('安装目录已被替换，已保留当前文件，请检查项目技能列表。');
  await rm(key, { recursive: true, force: true });
  ownedFolders.delete(key);
}
